<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$events=$pdo->query("SELECT DISTINCT e.id,e.name,e.event_date FROM bdc_events e JOIN bdc_scoring_rounds r ON r.event_id=e.id AND r.status<>'archived' ORDER BY e.event_date DESC,e.name")->fetchAll();$rounds=$pdo->query("SELECT r.id,r.event_id,r.division,r.round_type,r.scoring_mode,r.status FROM bdc_scoring_rounds r WHERE r.status<>'archived' ORDER BY r.event_id,r.division,FIELD(r.round_type,'heats','semifinal','final'),r.id")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Screen Projector | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.workspace{border:0;border-radius:16px}.option{border:1px solid #dee2e6;border-radius:12px;padding:18px;background:#fff}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../scoring/">BDC Scoring</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4"><div class="mb-4"><div class="text-uppercase text-danger fw-bold small">EVENT PRESENTATION</div><h1 class="h2">Live Screen Projector</h1><p class="text-muted">Select Event → Category → Round. Applicable projection options appear below.</p></div><div class="card workspace shadow-sm mb-4"><div class="card-body"><div class="row g-3"><div class="col-md-5"><label class="form-label fw-bold">Event</label><select id="event" class="form-select"><option value="">Select event...</option><?php foreach($events as $e):?><option value="<?=(int)$e['id']?>"><?=e($e['name'])?><?=!empty($e['event_date'])?' · '.e($e['event_date']):''?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label fw-bold">Category / Division</label><select id="division" class="form-select" disabled><option value="">Select category...</option></select></div><div class="col-md-3"><label class="form-label fw-bold">Round</label><select id="round" class="form-select" disabled><option value="">Select round...</option></select></div></div></div></div><div id="selected" class="d-none"><div class="d-flex justify-content-between align-items-center mb-3"><div><div class="small text-muted">SELECTED COMPETITION</div><h2 id="selectedTitle" class="h4 mb-0"></h2></div><a id="control" class="btn btn-danger">Screen & Layout Settings</a></div><div id="options" class="row g-3"></div></div></main><script>const rounds=<?=json_encode($rounds,JSON_UNESCAPED_SLASHES)?>,event=document.querySelector('#event'),division=document.querySelector('#division'),round=document.querySelector('#round');const label=s=>String(s).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());function divisions(){const id=Number(event.value),vals=[...new Set(rounds.filter(r=>Number(r.event_id)===id).map(r=>r.division))];division.innerHTML='<option value="">Select category...</option>'+vals.map(v=>`<option value="${v}">${label(v)}</option>`).join('');division.disabled=!id;round.innerHTML='<option value="">Select round...</option>';round.disabled=true;document.querySelector('#selected').classList.add('d-none')}function roundOptions(){const id=Number(event.value),d=division.value,vals=rounds.filter(r=>Number(r.event_id)===id&&r.division===d);round.innerHTML='<option value="">Select round...</option>'+vals.map(r=>`<option value="${r.id}" data-type="${r.round_type}">${label(r.round_type)}</option>`).join('');round.disabled=!d;document.querySelector('#selected').classList.add('d-none')}function show(){const r=rounds.find(x=>Number(x.id)===Number(round.value));if(!r){document.querySelector('#selected').classList.add('d-none');return}const eventName=event.options[event.selectedIndex].text.split(' · ')[0];document.querySelector('#selectedTitle').textContent=eventName+' · '+label(r.division)+' · '+label(r.round_type);document.querySelector('#control').href='control.php?round_id='+r.id;const types=r.round_type==='heats'?[['judges','Judges'],['competitors','Competitors'],['scoring','Scoring Status'],['callbacks','Callback Reveal']]:r.round_type==='semifinal'?[['judges','Judges'],['competitors','Competitors'],['scoring','Scoring Status'],['finalists','Finalists Reveal']]:[['judges','Judges'],['competitors','Finalists / Couples'],['scoring','Scoring Status'],['results','Final Ranking'],['winners','Winner Reveal']];document.querySelector('#options').innerHTML=types.map(t=>`<div class="col-md-6"><div class="option h-100"><h3 class="h5">${t[1]}</h3><p class="text-muted small">Projection for selected ${label(r.round_type)}.</p><a class="btn btn-outline-danger" href="projection.php?round_id=${r.id}&type=${t[0]}" target="_blank">Open Projection</a></div></div>`).join('');document.querySelector('#selected').classList.remove('d-none')}event.onchange=divisions;division.onchange=roundOptions;round.onchange=show;</script></body></html>